public class StringBasicsOverview {
    public static void main(String[] args) {
        // String literal in String Constant Pool
        String greeting = "Hello, Java!";

        // String created with new operator in Heap
        String objGreeting = new String("Hello, Java!");

        System.out.println("Greeting: " + greeting);
        System.out.println("Length: " + greeting.length());
        System.out.println("Content equality: " + greeting.equals(objGreeting));
        System.out.println("Reference identity: " + (greeting == objGreeting));
    }
}

public class StringDeclaration {
    public static void main(String[] args) {
        // 1. Literal initialization (uses String Pool)
        String s1 = "Welcome to Java";

        // 2. Using new keyword (forces separate heap object)
        String s2 = new String("Welcome to Java");

        // 3. From a character array
        char[] charArray = {'J', 'a', 'v', 'a'};
        String s3 = new String(charArray);

        System.out.println("Literal: " + s1);
        System.out.println("Object:  " + s2);
        System.out.println("From char[]: " + s3);
    }
}

public class StringMemoryModel {
    public static void main(String[] args) {
        String str1 = "OpenAI";
        String str2 = "OpenAI";
        String str3 = new String("OpenAI");

        // str1 and str2 refer to the identical pooled instance
        System.out.println("str1 == str2: " + (str1 == str2)); // true

        // str3 refers to a distinct heap instance
        System.out.println("str1 == str3: " + (str1 == str3)); // false

        // Interning str3 returns the pooled reference
        System.out.println("str1 == str3.intern(): " + (str1 == str3.intern())); // true
    }
}

