public class SuffixCaseSensitivity {
    public static void main(String[] args) {
        String photo = "vacation_photo.JPG";

        System.out.println("endsWith('.jpg'): " + photo.endsWith(".jpg")); // false
        System.out.println("endsWith('.JPG'): " + photo.endsWith(".JPG")); // true

        // Case-insensitive suffix verification
        boolean isJpeg = photo.toLowerCase().endsWith(".jpg");
        System.out.println("Normalized check: " + isJpeg); // true
    }
}

