public class StringReviewAlgorithms {
    public static void main(String[] args) {
        String phrase = "Race a car";
        System.out.println("Is '" + phrase + "' palindrome: " + isPalindrome(phrase));

        String s1 = "anagram", s2 = "nagaram";
        System.out.println("Are anagrams: " + areAnagrams(s1, s2));
    }

    public static boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            while (i < j && !Character.isLetterOrDigit(s.charAt(i))) i++;
            while (i < j && !Character.isLetterOrDigit(s.charAt(j))) j--;
            if (Character.toLowerCase(s.charAt(i)) != Character.toLowerCase(s.charAt(j))) {
                return false;
            }
            i++; j--;
        }
        return true;
    }

    public static boolean areAnagrams(String a, String b) {
        if (a.length() != b.length()) return false;
        int[] freq = new int[256];
        for (char c : a.toCharArray()) freq[c]++;
        for (char c : b.toCharArray()) {
            if (--freq[c] < 0) return false;
        }
        return true;
    }
}

public class StringTypesComparison {
    public static void main(String[] args) {
        // String: Immutable
        String s = "Hello";
        s.concat(" World");
        System.out.println("String: " + s); // Still "Hello"

        // StringBuilder: Mutable & fast (single-thread)
        StringBuilder sb = new StringBuilder("Hello");
        sb.append(" World");
        System.out.println("StringBuilder: " + sb); // "Hello World"

        // StringBuffer: Mutable & synchronized (thread-safe)
        StringBuffer sbf = new StringBuffer("Hello");
        sbf.append(" World");
        System.out.println("StringBuffer:  " + sbf); // "Hello World"
    }
}

public class PhoneFormatter {
    public static void main(String[] args) {
        String[] samples = {
            "1 (800) 555-0199",
            "917.555.4321",
            "2125557890",
            "+1-888-456-7890"
        };
        for (String sample : samples) {
            System.out.println(sample + " -> " + formatPhoneNumber(sample));
        }
    }

    public static String formatPhoneNumber(String raw) {
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < raw.length(); i++) {
            char c = raw.charAt(i);
            if (Character.isDigit(c)) {
                digits.append(c);
            }
        }

        // Strip leading US country code if 11 digits
        if (digits.length() == 11 && digits.charAt(0) == '1') {
            digits.deleteCharAt(0);
        }

        if (digits.length() != 10) {
            throw new IllegalArgumentException("Expected 10 digits, found: " + digits.length());
        }

        return String.format("(%s) %s-%s",
            digits.substring(0, 3),
            digits.substring(3, 6),
            digits.substring(6, 10)
        );
    }
}

